export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4;
  const g = inputs.gravity ?? 9.8;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const dur = (2 * u) / g;
  const currentT = Math.min(Math.max(time, 0), dur);

  const tossedY = u * currentT - 0.5 * g * currentT * currentT;
  const tossedV = u - g * currentT;
  const tossedA = -g;

  let dropY = yTop;
  let dropV = 0;
  let dropA = 0;
  let gateOpen = false;

  if (currentT >= tTop) {
    gateOpen = true;
    const dt = currentT - tTop;
    dropY = yTop - 0.5 * g * dt * dt;
    dropV = -g * dt;
    dropA = -g;
  }

  let tossedState = "At launch";
  if (Math.abs(currentT - tTop) < 0.005) {
    tossedState = "At the top";
  } else if (currentT < tTop) {
    tossedState = "Rising";
  } else if (Math.abs(currentT - dur) < 0.005) {
    tossedState = "At launch height";
  } else {
    tossedState = "Falling";
  }

  let dropState = "Held in place";
  if (currentT >= tTop) {
    if (Math.abs(currentT - tTop) < 0.005) {
      dropState = "Just released";
    } else if (Math.abs(currentT - dur) < 0.005) {
      dropState = "At launch height";
    } else {
      dropState = "Falling together";
    }
  }

  const pxPerM = 120;
  const groundY = 350;
  const tossX = 160;
  const dropX = 480;

  const tossPxY = groundY - tossedY * pxPerM;
  const dropPxY = groundY - dropY * pxPerM;
  const apexPxY = groundY - yTop * pxPerM;

  const objects = [];

  const tossPanel = sdk.panel({
    id: "lane.toss",
    x: 20,
    y: 20,
    w: 280,
    h: 380,
    title: "Toss lane",
    state: tossedState
  });
  objects.push(...tossPanel);

  const dropPanel = sdk.panel({
    id: "lane.drop",
    x: 340,
    y: 20,
    w: 280,
    h: 380,
    title: "Drop lane",
    state: dropState
  });
  objects.push(...dropPanel);

  objects.push(sdk.axis("axis.toss", {
    x: 60,
    y: groundY,
    length: 270,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.axis("axis.drop", {
    x: 380,
    y: groundY,
    length: 270,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.line("ref.toss.ground", 60, groundY, 280, groundY, { role: "neutral", opacity: 0.3 }));
  objects.push(sdk.line("ref.drop.ground", 380, groundY, 600, groundY, { role: "neutral", opacity: 0.3 }));

  objects.push(sdk.line("ref.toss.apex", 60, apexPxY, 280, apexPxY, { role: "neutral", opacity: 0.4 }));
  objects.push(sdk.line("ref.drop.apex", 380, apexPxY, 600, apexPxY, { role: "neutral", opacity: 0.4 }));

  objects.push(sdk.circle("ball.toss", tossX, tossPxY, 28, { role: "learner" }));
  const tossVecV = sdk.vector("vec.v.toss", { x: tossX - 22, y: tossPxY }, {
    value: tossedV,
    direction: "up",
    scale: 25,
    label: "v",
    role: "output"
  });
  const tossVecA = sdk.vector("vec.a.toss", { x: tossX + 22, y: tossPxY }, {
    value: tossedA,
    direction: "up",
    scale: 8,
    label: "a",
    role: "warning"
  });
  objects.push(...tossVecV, ...tossVecA);

  const tossCallout = sdk.callout(tossX + 45, tossPxY - 20, [
    `v = ${sdk.format(tossedV, 2)} m/s`,
    `a = ${sdk.format(tossedA, 2)} m/s²`
  ], { id: "callout.toss" });
  objects.push(...tossCallout);

  const gateObjs = sdk.gate("gate", dropX, apexPxY, {
    open: gateOpen,
    w: 40,
    label: "Apex Gate"
  });
  objects.push(...gateObjs);

  objects.push(sdk.circle("ball.drop", dropX, dropPxY, 28, { role: "prediction" }));
  const dropVecV = sdk.vector("vec.v.drop", { x: dropX - 22, y: dropPxY }, {
    value: dropV,
    direction: "up",
    scale: 25,
    label: "v",
    role: "output"
  });
  const dropVecA = sdk.vector("vec.a.drop", { x: dropX + 22, y: dropPxY }, {
    value: dropA,
    direction: "up",
    scale: 8,
    label: "a",
    role: "warning"
  });
  objects.push(...dropVecV, ...dropVecA);

  const dropCallout = sdk.callout(dropX + 45, dropPxY - 20, [
    `v = ${sdk.format(dropV, 2)} m/s`,
    `a = ${sdk.format(dropA, 2)} m/s²`
  ], { id: "callout.drop" });
  objects.push(...dropCallout);

  const readouts = [
    { id: "tossedVelocity", value: tossedV },
    { id: "tossedAcceleration", value: tossedA },
    { id: "dropVelocity", value: dropV },
    { id: "dropAcceleration", value: dropA }
  ];

  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime: tTop,
    apexHeight: yTop,
    tossedVelocity: tossedV,
    tossedAcceleration: tossedA,
    tossedHeight: tossedY,
    dropVelocity: dropV,
    dropAcceleration: dropA,
    dropHeight: dropY
  };

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts
    },
    quantities
  };
}
